{
  "cvars": {
    "ivs": [
      {
        "description": "Reader View condition: whether the modified 'Reader View' layout was activated (1) or not (0). This is the experimental manipulation whose effect on reading speed we estimate.",
        "columns": [
          "reader_view"
        ]
      }
    ],
    "dv": {
      "description": "Reading speed. To reduce skew and make effect sizes interpretable on a multiplicative scale we model the natural log of the per-trial reading speed measure ('speed') as the dependent variable.",
      "columns": [
        "log_speed"
      ]
    },
    "controls": [
      {
        "description": "Binary indicator for whether the reader has dyslexia (1) or not (0). Treated as a moderator: the main question asks whether reader_view has a different effect for readers with dyslexia.",
        "is_moderator": true,
        "moderator_on": "reader_view",
        "columns": [
          "is_dyslexic"
        ]
      },
      {
        "description": "Number of words on the page; longer texts will tend to change reading time and thus speed and should be controlled for.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "num_words"
        ]
      },
      {
        "description": "Age of the reader in years; included as a demographic control.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "age"
        ]
      },
      {
        "description": "Device used by the reader (categorical: e.g., smartphone, tablet, desktop). Mode of presentation/interaction can affect reading speed and is included as a categorical control (entered in the model using C(device)).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "device"
        ]
      },
      {
        "description": "Flesch-Kincaid readability score of the text; text difficulty affects reading speed and is included as a numeric control.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Flesch_Kincaid"
        ]
      },
      {
        "description": "Whether the reader is a native English speaker (categorical 'Y'/'N'); language fluency can influence speed and is included as a categorical control (entered as C(english_native)).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "english_native"
        ]
      },
      {
        "description": "Indicator whether the trial was a retake (1) or not (0); retake trials might have systematically different speeds so include as a control.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "retake_trial"
        ]
      },
      {
        "description": "Page identifier: include as a categorical fixed effect (entered as C(page_id)) so that differences in content between pages are absorbed.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "page_id"
        ]
      },
      {
        "description": "Participant identifier used for clustered standard errors (we do not include as a fixed effect here but cluster SEs by uuid to account for within-subject correlation).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "uuid"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Transform raw dataset into the analysis dataframe.\n    Produces these columns (used by the model):\n      - uuid, page_id, reader_view, log_speed, is_dyslexic,\n        num_words, age, device, Flesch_Kincaid, english_native, retake_trial\n\n    Steps:\n      - drop rows missing the core variables\n      - construct an explicit binary dyslexia indicator (is_dyslexic)\n      - compute log_speed = log(speed) to reduce skew\n      - keep only columns required for modeling\n    \"\"\"\n    df = df.copy()\n\n    # Ensure required columns exist\n    required = ['speed', 'reader_view', 'num_words', 'page_id', 'uuid']\n    for c in required:\n        if c not in df.columns:\n            raise KeyError(f\"Required column '{c}' not found in dataframe\")\n\n    # Prefer an existing dyslexia binary if present, otherwise derive from 'dyslexia'\n    if 'dyslexia_bin' in df.columns:\n        df['is_dyslexic'] = df['dyslexia_bin'].astype(float).fillna(0).astype(int)\n    elif 'dyslexia' in df.columns:\n        # dyslexia: 0=no, 1=dyslexia, 2=severe -> treat any >=1 as dyslexic\n        df['is_dyslexic'] = (df['dyslexia'].fillna(0) >= 1).astype(int)\n    else:\n        # if no dyslexia indicator available, create a column of zeros (no dyslexia info)\n        df['is_dyslexic'] = 0\n\n    # Drop rows with missing values in the key variables used in the model\n    keep_cols = ['speed', 'reader_view', 'is_dyslexic', 'num_words', 'age', 'device',\n                 'Flesch_Kincaid', 'english_native', 'retake_trial', 'page_id', 'uuid']\n    # Only drop NAs in columns that exist in the dataset; otherwise keep the row (we already created defaults where necessary)\n    cols_to_check = [c for c in keep_cols if c in df.columns]\n    df = df.dropna(subset=cols_to_check)\n\n    # Filter unreasonable speed values (non-positive) and compute log speed\n    # Add small epsilon to avoid log(0) if there are extremely small positive values\n    df = df[df['speed'] > 0]\n    df['log_speed'] = np.log(df['speed'].astype(float).clip(lower=1e-6))\n\n    # Ensure types: reader_view should be numeric (0/1)\n    df['reader_view'] = pd.to_numeric(df['reader_view'], errors='coerce').astype(int)\n\n    # Keep only the columns needed for modeling (this is our final dataframe)\n    final_cols = [c for c in ['uuid', 'page_id', 'reader_view', 'log_speed', 'is_dyslexic', 'num_words', 'age', 'device', 'Flesch_Kincaid', 'english_native', 'retake_trial'] if c in df.columns]\n    df = df[final_cols].reset_index(drop=True)\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame):\n    \"\"\"\n    Fit an OLS model of log reading speed on Reader View, moderation by dyslexia,\n    and controls. We include categorical fixed effects for device and page_id and\n    cluster standard errors by participant uuid to account for within-subject correlation.\n\n    Model formula:\n      log_speed ~ reader_view * is_dyslexic + C(device) + num_words + age + Flesch_Kincaid + C(english_native) + retake_trial + C(page_id)\n\n    Returns the fitted results object (statsmodels regression results).\n    \"\"\"\n    import statsmodels.formula.api as smf\n\n    # Verify required columns\n    model_cols = ['log_speed', 'reader_view', 'is_dyslexic', 'num_words', 'age', 'device', 'Flesch_Kincaid', 'english_native', 'retake_trial', 'page_id', 'uuid']\n    missing = [c for c in model_cols if c not in df.columns]\n    if missing:\n        raise KeyError(f\"Dataframe is missing required columns for model: {missing}\")\n\n    # Build formula. Use categorical encoding for device, english_native and page_id\n    formula = ('log_speed ~ reader_view * is_dyslexic + C(device) + num_words + age '\n               '+ Flesch_Kincaid + C(english_native) + retake_trial + C(page_id)')\n\n    # Fit OLS and compute cluster-robust standard errors by participant (uuid)\n    model = smf.ols(formula, data=df)\n    results = model.fit(cov_type='cluster', cov_kwds={'groups': df['uuid']})\n\n    # Return the fitted results object so the caller can inspect coefficients, summary, confidence intervals, etc.\n    return results\n"
}
